  Fu = `Gebruik de knop aan de rechterkant om een beoordeling aan te vragen van je pagina. Doe dit minstens 7 dagen voor de datum waarop je wenst te publiceren, zodat er voldoende tijd is om de pagina te beoordelen, goed te keuren en de nodige wijzigingen te maken.`,
  Iu = `Als er wijzigingen nodig zijn aan je pagina, dan neemt het Steam-team contact met je op via je Steamworks-ondersteuningsticket. Je kunt dit ticket bekijken en er opmerkingen aan toevoegen door op de knop aan de rechterkant te klikken.`,
