  Bu = `Hiermee wordt een ticket aangemaakt om de verkooppagina te laten beoordelen, zodat die gepubliceerd kan worden. Verzend dit verzoek pas als alle definitieve illustraties en gewenste spellen aan de pagina zijn toegevoegd.`,
  Vu = `Als je een beoordeling aanvraagt, wordt er een Steamworks-ondersteuningsticket aangemaakt met het verzoek om je verkooppagina te laten beoordelen door Valve. Doe dit pas als je beeldmateriaal en tekst definitief zijn en de lijst met spellen compleet is.`,
  Hu = `Zorg ervoor dat de titel en het doel van je evenement duidelijk bovenaan de pagina worden weergegeven. Voor showcases moet je mogelijk een tekstvak toevoegen om te beschrijven wat je showcase is en hoe alles werkt.`,
  Uu = `De uitverkooppagina wordt vergrendeld zodra deze is beoordeeld. Als je nog wijzigingen wilt aanbrengen na de beoordeling of zodra het evenement is begonnen, vermeld dan in de opmerkingen wat die wijzigingen precies inhouden en waarom ze niet konden worden aangebracht vóór de beoordeling.`,
