  Gu = `Selecteer partners waarvan de leden ook toegang moeten krijgen tot dit ticket`,
  Ku = `Als deze optie wordt gekozen, kunnen andere leden van partners dit ticket ook openen en beantwoorden. De standaardinstelling is dat alleen jij het aangemaakte ticket kunt lezen, bewerken en beantwoorden (optioneel).`,
