  zV = `Wil je je stem veranderen?`,
  BV = `Je kunt maar op één spel stemmen voor elke categorie en je hebt al op %1$s gestemd voor de deze. Wil je je stem veranderen en uitbrengen op %2$s?`,
  VV = `Je account is mogelijk beperkt. Om te voorkomen dat er valsgespeeld wordt bij het nomineren, kunnen alleen accounts die 5 dollar (USD) hebben uitgegeven op Steam deelnemen aan de Steam Awards. %1$s voor meer informatie.`,
  HV = `Je account is mogelijk beperkt. Om te voorkomen dat er valsgespeeld wordt bij het stemmen, kunnen alleen accounts die 5 dollar (USD) hebben uitgegeven op Steam deelnemen aan de Steam Awards. %1$s voor meer informatie.`,
