  eH = `Het VR-spel van het jaar bootst de realiteit niet gewoon na. Het voert je naar een betere realiteit. Dit spel buit de mogelijkheden van VR als medium ten volle uit en verlegt de grenzen van de virtuele wereld.`,
  tH = `Dit spel is al even uit. Het team heeft zijn creatieve ei al een tijd geleden gelegd, maar deze ontwikkelaars − goede ouders dat het zijn − blijven erop broeden. Na al die jaren krijgt dit spel nog altijd nieuwe inhoud.`,
  nH = `Er zijn spellen die gewoon niet hetzelfde zijn wanneer je ze alleen speelt. Misschien heb je een vriend nodig die je dekking geeft. Misschien heb je een vriend nodig die je in de rug kunt steken. Er wacht hoe dan ook pret voor diegenen die hun vrienden optrommelen om dit spel te spelen.`,
  rH = `Grafische stijl betekent niet streven naar een echte grafische getrouwheid (hoewel dat een nobele doelstelling is), maar het beschrijft een unieke uitstraling en gevoel die een heel spel doordrenken.`,
